      var u = (n && n.action_url || '').trim(), c = (n && n.category || '').toLowerCase();
      if (u && u.charAt(0) === '/') return u;            // explicit path (e.g. /billing, /conversations/123)
      if (/deliverab/.test(u)) return '/reports';        // "open:deliverability-copilot"
      if (/credit|balance|low_credit|billing|payment|card|funds/.test(c)) return '/billing';
      if (/deliver|failure|carrier|reject|bounce|undeliver|spam/.test(c)) return '/sms/logs'; // outbound failures → SMS Logs (failed list), not the plain inbox
      if (/reply|inbound|message|conversation/.test(c)) return '/conversations';
      if (/dial|call|voicemail/.test(c)) return '/dialer';
