      var clean = path.split('?')[0];
      var seg = clean.split('/')[1] || '';
      var TAB = { conversations: 'inbox', inbox: 'inbox', billing: 'settings', settings: 'settings', reports: 'reports', dialer: 'dialer', crm: 'contacts', '10dlc': '10dlc', numbers: 'number-health', 'number-health': 'number-health', dashboard: 'dashboard' };
      var tab = TAB[seg] || 'inbox';
