    pop.innerHTML = _chatCats.map(function (c) { return '<button type="button" data-catpick="' + catEsc(c.name) + '" style="display:flex;align-items:center;gap:8px;width:100%;text-align:left;padding:8px 10px;border:0;background:none;border-radius:7px;font:inherit;font-size:13px;color:var(--ink,#111);cursor:pointer"><span style="width:8px;height:8px;border-radius:50%;background:' + (c.color || '#2563EB') + '"></span>' + catEsc(c.name) + '</button>'; }).join('')
      + '<button type="button" data-catpick="" style="display:flex;align-items:center;gap:8px;width:100%;text-align:left;padding:8px 10px;border:0;border-top:1px solid var(--hairline,#e5e7eb);background:none;font:inherit;font-size:12.5px;color:var(--muted,#6b7280);cursor:pointer;margin-top:4px">Remove from all</button>';
