    document.body.appendChild(pop);
    var pw = pop.offsetWidth || 200, ph = pop.offsetHeight || 240;
    var rRight = (r.right != null ? r.right : r.left + 180);
    var left = Math.max(8, Math.min(rRight - pw, window.innerWidth - pw - 8));
    var top = (r.bottom + 6 + ph <= window.innerHeight) ? (r.bottom + 6) : Math.max(8, r.top - ph - 6);
