    if (searchEl) searchEl.addEventListener('input', rerender);
    function place() { var r = btn.getBoundingClientRect(), pw = pop.offsetWidth, ph = pop.offsetHeight; pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - pw - 8)) + 'px'; pop.style.top = (r.top > ph + 12 ? r.top - ph - 6 : r.bottom + 6) + 'px'; }
    place();
    rsmsLoadTemplates().then(function () { if (pop.parentNode) { rerender(); place(); } });
    // Swap the footer into a name field prefilled from the message's first words.
