      var cEl = row.querySelector('[data-spintax-count]'); if (cEl) cEl.textContent = n.toLocaleString() + (n === 1 ? ' variant' : ' variants');
      var vEl = row.querySelector('[data-spintax-valid]');
      if (vEl) { vEl.textContent = ok ? '✓ braces balanced' : '⚠ unbalanced { } — fix before sending'; vEl.style.color = ok ? 'var(--good,#16a34a)' : 'var(--danger,#dc2626)'; vEl.style.fontWeight = '600'; }
