      'last name': 'contact.last_name', 'lastname': 'contact.last_name', 'lname': 'contact.last_name',
      'city': 'contact.city', 'city name': 'contact.city', 'town': 'contact.city',
      'state': 'contact.state', 'province': 'contact.state',
      'zip': 'contact.postal_code', 'zip code': 'contact.postal_code', 'zipcode': 'contact.postal_code',
