    if (cn) { e.preventDefault(); var dv = parseInt(cn.getAttribute('data-cal-nav'), 10) || 0; var b = _schedCalMonth || _schedFirstOfMonth(new Date()); _schedCalMonth = new Date(b.getFullYear(), b.getMonth() + dv, 1); renderSchedCal(); return; }
