    if (cp) { e.preventDefault(); var card = cp.closest('.auto-card'), m = card && card.querySelector('.tplx-msg'); try { navigator.clipboard.writeText(m ? m.textContent : ''); } catch (_e) {} if (window.__rsmsToast) window.__rsmsToast('Template copied'); return; }
