  // ---------- number health (real /phone-numbers health columns) -----------
  function nhRows() { return $('#pane-number-health [data-nhtab-panel="sms"] .nh-rows'); }
  function nhMsg(html) { var c = nhRows(); if (c) c.innerHTML = '<div style="padding:30px 8px;text-align:center;color:var(--muted);font-size:13px">' + html + '</div>'; }
  window.loadNumberHealth = loadNumberHealth;
  // ===== Number Health filter bar (client-side over the loaded list) =====
  // Every number already carries health_score, total_sent/delivered/opt_outs,
