    pager.innerHTML = '<button id="nhdial-pg-prev" type="button" class="nh-act" style="padding:6px 12px;font-size:12.5px"' + (_nhDialPage <= 0 ? ' disabled style="padding:6px 12px;font-size:12.5px;opacity:.4;cursor:default"' : '') + '>'
