        + '<div style="display:flex;align-items:center;justify-content:space-between;padding:15px 18px;border-bottom:1px solid var(--line,#eef0f4)"><div style="font-weight:700;font-size:15px;color:var(--ink)">' + esc(title) + '</div><button type="button" data-drill-close style="border:0;background:none;font-size:22px;line-height:1;color:var(--muted);cursor:pointer">&times;</button></div>'
