  function setDollarSel(sel, usd) { if (!sel || usd == null) return; var want = '$' + Math.round(usd); for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].text.replace(/\s/g, '') === want) { sel.selectedIndex = i; if (window.__rdsEnhance) try { window.__rdsEnhance(sel); } catch (e) {} return; } } }
  // Settings → Billing → "Plan & usage" (dialer) card. The dialer-pane wiring
