      var nm = u.company_name || ((u.first_name||'')+ ' ' +(u.last_name||'')).trim() || u.email || 'Account';
      var f = function(l,v){return '<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--hairline,#f1f5f9)"><span style="font-weight:600;color:var(--ink,#111)">'+l+'</span><span>'+esc(v)+'</span></div>';};
      ov.querySelector('.sam-bd').innerHTML = '<div style="font-weight:700;font-size:15px;color:var(--ink,#111);margin-bottom:12px">'+esc(nm)+'</div>'
        +f('Email',u.email||'\u2014')+f('Role',u.role||'\u2014')+f('Status',u.status||u.invite_status||'active')
