          + '<span class="acct-ava sm">' + esc(initials(nm)) + '</span>' + esc(nm)
          + (isCurrent ? '<svg width="14" height="14" fill="none" stroke="#10B981" stroke-width="2.5" viewBox="0 0 24 24" style="margin-left:auto"><polyline points="20 6 9 17 4 12"/></svg>' : '')
          + '</button>';
