    // Only use the localStorage (parent) token when impersonating a SUB and switching
    // to a sibling \u2014 that needs the top-level parent's authority. When impersonating a
    // PARENT (e.g. admin viewing Joe u28), the localStorage token is the admin's and
    // ISN'T the parent of Joe's children \u2192 /switch 404s. Use the impersonate token
    // (via api.request) so the switch runs with Joe's own parent authority.
    var isImp = !!(sessionStorage.getItem('readysms_impersonate_token') || new URLSearchParams(location.search).get('impersonate'));
    var rootTok = null; try { rootTok = sessionStorage.getItem('readysms_impersonate_root'); } catch (e) {}
    var impSub = isImp && me && me.parent_account_id;
