        + '<div style="padding:12px 20px 0"><label style="display:block;font-size:12px;font-weight:600;color:var(--ink,#111);margin-bottom:6px">Category</label>'
        + '<select id="dsp-cat" style="width:100%;box-sizing:border-box;padding:9px 11px;border:1px solid var(--hairline-strong,#d8dee9);border-radius:9px;font:inherit;font-size:13px;background:var(--card,#fff)">'
        + '<option value="positive">Positive</option><option value="negative">Negative</option><option value="callback">Callback</option><option value="neutral">Neutral</option></select></div>'
        + '<div style="padding:12px 20px 0"><label style="display:inline-flex;align-items:center;gap:7px;font-size:13px;color:var(--ink-2,#374151);cursor:pointer"><input id="dsp-term" type="checkbox"> Terminal (stops further dials)</label></div>'
