          if (r && r.success !== false) { var nd = (r.data || r.disposition || { id: Date.now(), label: label, category: ov.querySelector('#dsp-cat').value }); dispos.push(nd); renderDispos(); btoast('Outcome added'); ov.remove(); }
          else btoast((r && r.error) || 'Could not add outcome');
