    var _lastCoFreqIdx = document.getElementById('set-co-freq') ? document.getElementById('set-co-freq').selectedIndex : 0;
    var _lastCoFreqCustom = document.getElementById('set-co-freq-custom') ? document.getElementById('set-co-freq-custom').value : '';
    var _lastCoKw = document.getElementById('set-co-kw') ? document.getElementById('set-co-kw').value : '';

