        return '<div style="display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid var(--hairline,#f0f2f5)">'
          + '<div style="min-width:0"><span class="' + cls + '">' + esc(t.name) + '</span>' + def + kw + '</div>'
          + '<div style="display:flex;gap:6px;flex:none;align-items:flex-start">'
          + '<button type="button" data-edittag="' + t.id + '" style="' + btn + '">Edit</button>'
