        { id: 0, name: 'Not Interested', category: 'fail', is_terminal: true }, { id: 0, name: 'Wrong Number', category: 'fail', is_terminal: true },
        { id: 0, name: 'Do Not Call', category: 'fail', is_terminal: true }
