          + '<div style="padding:18px 20px;display:flex;justify-content:flex-end;gap:8px">'
          + '<button id="dset-dsp-cancel" type="button" style="padding:9px 14px;border:1px solid var(--hairline-strong,#d8dee9);background:#fff;border-radius:9px;font:inherit;font-size:13px;cursor:pointer">Cancel</button>'
          + '<button id="dset-dsp-save" type="button" style="padding:9px 16px;border:0;background:var(--accent,#2563EB);color:#fff;border-radius:9px;font:inherit;font-size:13px;font-weight:600;cursor:pointer">Add</button>'
          + '</div></div>';
        document.body.appendChild(ov);
        // Use the app's styled dropdown instead of the native (dark/unbranded) select.
