          function attrOpts(sel) { return cat.attributes.map(function (a) { return '<option value="' + a.key + '"' + (a.key === sel ? ' selected' : '') + '>' + esc(a.label) + '</option>'; }).join(''); }
          function opOpts(type, sel) { return _opsFor(type, cat).map(function (o) { return '<option value="' + o.key + '"' + (o.key === sel ? ' selected' : '') + '>' + esc(o.label) + '</option>'; }).join(''); }
