        var fld = 'width:100%;box-sizing:border-box;padding:9px 11px;border:1px solid var(--hairline-strong,#d8dee9);border-radius:9px;font:inherit;font-size:13px';
        var lbl = 'display:block;font-size:12px;font-weight:600;color:var(--ink,#111);margin-bottom:6px';
        ov.innerHTML = '<div style="background:var(--card,#fff);border-radius:14px;width:100%;max-width:440px;box-shadow:0 20px 60px rgba(0,0,0,.25)">'
