          + '<div style="padding:12px 20px 0"><label style="' + lbl + '">Send events</label><div style="display:flex;flex-wrap:wrap;gap:9px 16px;font-size:13px;color:var(--ink,#111)">'
          + [['call.connected', 'Call connected'], ['call.ended', 'Call ended'], ['outcome.set', 'Outcome set'], ['voicemail.dropped', 'Voicemail dropped'], ['recording.ready', 'Recording ready']].map(function (o) { return '<label style="display:inline-flex;align-items:center;gap:7px;cursor:pointer"><input type="checkbox" class="ow-ev" value="' + o[0] + '"> ' + o[1] + '</label>'; }).join('')
          + '</div></div>'
          + '<div style="padding:12px 20px 0"><label style="' + lbl + '">Limit to outcomes <span style="font-weight:400;color:var(--muted)">(optional; only when just \u201cOutcome set\u201d is selected)</span></label><input id="ow-trig" type="text" placeholder="Interested, Appointment Set" style="' + fld + '"></div>'
          + '<div style="padding:12px 20px 0"><label style="' + lbl + '">Signing secret <span style="font-weight:400;color:var(--muted)">(optional)</span></label><input id="ow-secret" type="text" placeholder="Signs the X-RSMS-Signature header" style="' + fld + '"></div>'
          + '<div style="padding:18px 20px;display:flex;justify-content:flex-end;gap:8px">'
