          + '<button id="ow-save" type="button" style="padding:9px 16px;border:0;background:var(--accent,#2563EB);color:#fff;border-radius:9px;font:inherit;font-size:13px;font-weight:600;cursor:pointer">' + (existing ? 'Save' : 'Add destination') + '</button>'
