            + '<button type="button" class="dwh-rule-del" style="background:none;border:0;cursor:pointer;color:var(--faint);display:inline-flex;padding:0" title="Delete rule"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>'
            + '</span></div>'
            + '<div class="dwh-rule-then">\u2192 Text: <span class="dwh-msg">\u201c' + esc(r.template_body || '') + '\u201d</span></div>'
            + '</div>';
