        + '<button type="button" id="dlf-start-dialing" style="height:36px;padding:0 16px;font:inherit;font-size:13px;font-weight:650;display:inline-flex;align-items:center;gap:6px;border:0;border-radius:8px;background:var(--accent,#2563EB);color:#fff;cursor:pointer">Open dialer<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></svg></button>';
