        var reply = (out && (out.reply || out.text || out.message || out.draft)) || '';
        var escalated = out && (out.escalate || out.escalated);
        try { think.parentNode.removeChild(think); } catch (e) {}
        if (escalated && !reply) { bubble('outbound', '<span style="display:inline-flex;align-items:center;gap:6px;color:var(--accent-deep);font-weight:600"><span style="color:var(--accent-deep);display:inline-flex">' + airIco('hand_off', 14) + '</span>Hands this off to a human here.</span>'); return; }
