    // Parse-race guard (see loadContacts): bail-once on a not-yet-parsed pane leaks sample brand cards.
    if (!pane) { if ((loadTenDlc._tries = (loadTenDlc._tries || 0) + 1) <= 40) setTimeout(function(){ loadTenDlc(live); }, 120); return; }
    loadTenDlc._tries = 0;
