      var regs = unwrap(await api.getTenDlcStatus(live)); if (!Array.isArray(regs)) regs = (regs && regs.data) || [];
      // Signature of (id:status) — the review poll re-renders ONLY when this changes
      // (e.g. a brand flips to Approved), so it never jarringly rebuilds the whole
      // pane every 25s while nothing's changed. The card's own 5s animation handles
      // the smooth progress.
      try { window.__dlcLastSig = regs.map(function (r) { return r.id + ':' + (r.status || ''); }).sort().join('|'); } catch (_) {}
      var brands = regs.filter(function (r) { return r.type === 'brand' || !r.type; });
      var camps = regs.filter(function (r) { return r.type === 'campaign'; });
      // The "Why do I have to do this?" explainer is onboarding for first-timers —
