    var html = '<div style="display:flex;flex-wrap:wrap;gap:8px 20px;padding:0 0 14px;border-bottom:1px solid var(--line,#eef0f4);margin-bottom:14px">'
      + '<div style="display:flex;align-items:center;gap:8px"><span style="font-size:12px;color:var(--muted);font-weight:600">Match by</span>'
      + chip('by', 'phone', has('phone'), 'Phone') + chip('by', 'email', has('email'), 'Email') + chip('by', 'name', has('name'), 'Name') + multiHint + '</div>'
      + '<div style="display:flex;align-items:center;gap:8px"><span style="font-size:12px;color:var(--muted);font-weight:600">Scan</span>'
      + chip('scope', 'all', _dupScope === 'all', 'All contacts') + chip('scope', 'filter', _dupScope === 'filter', hasF ? 'Current filter' : 'Current filter (none set)', !hasF) + '</div></div>';
    var bar = document.getElementById('dup-controls');
