    crmDupControls();
    var byEl = $('#crm-dupes-by'); if (byEl) byEl.textContent = _dupByList.join(' + ');
    var cnt = $('#crm-dupes-count'), allBtn = $('#crm-dupes-all'), tagBtn = $('#crm-dupes-tag');
    if (cnt) cnt.textContent = 'Scanning…';
    if (allBtn) allBtn.style.display = 'none';
    if (tagBtn) tagBtn.style.display = 'none';
    var stopAnim = crmDupScanAnim(body);
    var minRun = new Promise(function (r) { setTimeout(r, 2500); }); // min visible runtime
    var qp = ['by=' + encodeURIComponent(_dupByList.join(','))];
    if (_dupScope === 'filter') { var fp = crmDupFilterParams(); Object.keys(fp).forEach(function (kk) { qp.push(encodeURIComponent(kk) + '=' + encodeURIComponent(fp[kk])); }); }
