    if (btn && btn.disabled) return; // already submitting
    var get = function (id) { var el = document.getElementById(id); return el ? el.value.trim() : ''; };
    var phone = get('ac-phone');
    if (!phone) { if (window.__rsmsToast) window.__rsmsToast('Add a phone number first'); return; }
    // US-only platform: reject a fake/over-long area code at entry. Otherwise the
    // contact saves but every future send to it dies silently at the quiet-hours
    // timezone gate (unknown_tz) — the Aiden Taylor failure mode. Same 426-code
    // NANP map quiet-hours uses (window.__rsmsUsNumberOk).
