    if (_crmSeqMap == null) { _crmSeqMap = {}; try { var sq = unwrap(await api.getDripSequencesLight()) || []; if (!Array.isArray(sq)) sq = sq.sequences || sq.data || []; sq.forEach(function (s) { if (s && s.name != null) _crmSeqMap[s.name] = s.id; }); } catch (e) {} }
