  // and routes Save-as-draft / Schedule / Send through the consent-gated API.
  var _segCache = null, _contactCache = null, _countTimer = null;
  function bid(id) { return document.getElementById(id); }
  function bval(id) { var e = bid(id); return e ? ('' + (e.value || '')).trim() : ''; }
  function bchk(id) { var e = bid(id); return !!(e && e.checked); }
  // The schedule/stop date fields are custom calendar pickers (readonly, value
