      var sels = row.querySelectorAll('.blast-select'); if (sels.length < 3) return;
      var field = (sels[0].value || '').toLowerCase();
      var notOp = /not/.test((sels[1].value || 'is').toLowerCase());
      var operator = notOp ? 'not_equals' : 'equals';
      var val = (sels[2].value || '').trim(); if (!val) return;
