  var ACT_OK = { send_sms: 1, add_tag: 1, remove_tag: 1, route_category: 1, update_field: 1, set_dnd: 1, move_pipeline: 1, notify: 1, ai_prompt: 1, ai_responder: 1, webhook: 1, branch: 1, switch: 1, ab_split: 1, add_to_drip: 1, remove_from_drip: 1, update_score: 1, assign_user: 1, create_task: 1, connect_app: 1 };
