  // ===== Blast Filter → Tag dropdown → REAL tags ============================
  // The Filter recipient mode's "Tag is ___" value dropdown was hardcoded demo tags
  // ("Open house sign-in", "Hot buyer"…). Kevin couldn't filter by his own tags. Pull
  // the account's real distinct tags from /contacts/tags.
  // Re-sync a custom .rds dropdown's visible menu to its <select> options. __rdsEnhance
  // is a no-op on already-enhanced selects (data-rds guard), so after changing options we
  // must rebuild the .rds-menu + trigger label ourselves.
  function syncRds(sel) {
    var wrap = sel.closest && sel.closest('.rds');
    if (!wrap) { if (window.__rdsEnhance) try { window.__rdsEnhance(sel); } catch (e) {} return; }
    var CK = '<svg class="rds-ck" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';
    var menu = wrap.querySelector('.rds-menu');
    if (menu) {
      var h = '';
      for (var i = 0; i < sel.options.length; i++) { var o = sel.options[i]; h += '<div class="rds-o' + (i === sel.selectedIndex ? ' rds-on' : '') + '" role="option" data-i="' + i + '">' + CK + '<span>' + esc(o.text) + '</span></div>'; }
      menu.innerHTML = h;
    }
    var val = wrap.querySelector('.rds-val'); if (val) { var c = sel.options[sel.selectedIndex]; val.textContent = c ? c.text : ''; }
  }
  var _bmTagsCache = null;
  // Blast "Build from filter" was BROKEN: recipientFields() emitted the display LABELS
  // ("Tag","Pipeline stage") as the rule.field, which buildFilterSQL ignores → 0 clauses
  // → the backend matched ALL contacts (a blast-to-everyone footgun). Mirror the dialer
  // builder: real field keys, per-field operators, and a value dropdown per field.
  // Read the blast filter rows into backend filter-rule objects (label → buildFilterSQL key).
  function bmReadFilterRules() {
    var fp = $('#blast-modal [data-rpane="filter"]'); if (!fp) return [];
    var rules = [];
    $all('.bm-filter-row', fp).forEach(function (row) {
      var sels = row.querySelectorAll('select'); if (sels.length < 3) return;
      var field = ((sels[0].options[sels[0].selectedIndex] || {}).text || sels[0].value || '').toLowerCase();
      var notOp = /not/.test(((sels[1].options[sels[1].selectedIndex] || {}).text || sels[1].value || 'is').toLowerCase());
      var val = (sels[2].value || '').trim(); if (!val) return;
      // NB: "stage" contains the substring "tag" — match stage/activity first.
      if (/stage/.test(field)) rules.push({ field: 'pipeline_stage', operator: notOp ? 'not_equals' : 'equals', value: val });
      else if (/activity/.test(field)) { var p = val.split(':'); if ((p[0] === 'days_ago_less' || p[0] === 'days_ago_more') && p[1]) rules.push({ field: 'last_activity', operator: p[0], value: p[1] }); }
      else if (/tag/.test(field)) rules.push({ field: 'tags', operator: notOp ? 'not_contains' : 'contains', value: val });
    });
    return rules;
  }
  // Field dropdown ships "Tag / List / Last activity / Pipeline stage" — "List" was never
  // wired and is ambiguous. Rebuild (once/row) to the three fields that map cleanly.
  function bmEnsureFilterFields(row) {
    var fs = row.querySelector('select'); if (!fs || fs.__bmFields) return; fs.__bmFields = 1;
    var have = [].map.call(fs.options, function (o) { return o.text; });
    if (have.indexOf('List') < 0) return; // already a clean set
    var cur = fs.value;
    fs.innerHTML = ['Tag', 'Pipeline stage', 'Last activity'].map(function (l) { return '<option' + (l === cur ? ' selected' : '') + '>' + l + '</option>'; }).join('');
    syncRds(fs);
  }
  // Populate a row's value dropdown to match its field: Tag → real tags; Pipeline stage →
  // canonical funnel; Last activity → date presets (operator encoded in the option value).
  async function bmFillFilterValues(row) {
    var sels = row.querySelectorAll('select'); if (sels.length < 3) return;
    bmEnsureFilterFields(row);
    var field = ((sels[0].options[sels[0].selectedIndex] || {}).text || '').toLowerCase(); var v = sels[2];
    if (/stage/.test(field)) {
      if (v.__bmKind === 'stage') return;
      v.innerHTML = dlcStageOpts().map(function (s) { return '<option value="' + esc(s.value) + '">' + esc(s.label) + '</option>'; }).join('');
      v.__bmKind = 'stage'; syncRds(v);
    } else if (/activity/.test(field)) {
      if (v.__bmKind === 'activity') return;
      var A = [['days_ago_less:7', 'in the last 7 days'], ['days_ago_less:14', 'in the last 14 days'], ['days_ago_less:30', 'in the last 30 days'], ['days_ago_more:30', 'more than 30 days ago'], ['days_ago_more:90', 'more than 90 days ago']];
      v.innerHTML = A.map(function (d) { return '<option value="' + d[0] + '">' + esc(d[1]) + '</option>'; }).join('');
      v.__bmKind = 'activity'; syncRds(v);
    } else if (/tag/.test(field)) {
      if (v.__bmKind === 'tag' && v.value) return;
      if (_bmTagsCache == null) { try { var d = unwrap(await api.request('GET', '/contacts/tags')); _bmTagsCache = Array.isArray(d) ? d : (d && d.data) || []; } catch (e) { _bmTagsCache = []; } }
      var tags = (_bmTagsCache || []).map(function (t) { return typeof t === 'string' ? t : (t.tag || t.name || ''); }).filter(Boolean);
      var cur = v.value;
      v.innerHTML = tags.length ? tags.map(function (t) { return '<option' + (t === cur ? ' selected' : '') + '>' + esc(t) + '</option>'; }).join('') : '<option value="">No tags yet — add tags in your CRM</option>';
      v.__bmKind = 'tag'; syncRds(v);
    }
  }
  // Kept the bmFillFilterTags name (existing call sites) — now fills every row's value
  // dropdown for ANY field, not just Tag.
  async function bmFillFilterTags() {
    var M = document.getElementById('blast-modal'); if (!M) return;
    var rows = $all('.bm-filter-row', M); if (!rows.length) return;
    for (var i = 0; i < rows.length; i++) { await bmFillFilterValues(rows[i]); }
  }
