        try { var cd = unwrap(await api.request('GET', '/campaigns')); var all = Array.isArray(cd) ? cd : (cd && cd.data) || []; blasts = all.filter(function (b) { return b && b.status && b.status !== 'draft'; }); } catch (e2) {}
        setBadge(jobs.filter(function (j) { return j.status === 'processing' || j.status === 'queued'; }).length);
