          if (cb) { var jid = cb.getAttribute('data-jid'); cb.disabled = true; cb.textContent = 'Cancelling…'; api.request('POST', '/bulk-jobs/' + jid + '/cancel').then(function () { loadPanel(body); }).catch(function () { loadPanel(body); }); return; }
          var dl = e.target.closest && e.target.closest('.rsms-ba-del');
          if (dl) { var jd = dl.getAttribute('data-jid'); dl.disabled = true; dl.textContent = '…'; api.request('DELETE', '/bulk-jobs/' + jd).then(function () { loadPanel(body); }).catch(function () { loadPanel(body); }); return; }
          var bp = e.target.closest && e.target.closest('.rsms-blast-pause');
          if (bp) { var bid = bp.getAttribute('data-bid'); bp.disabled = true; bp.textContent = '…'; api.request('POST', '/campaigns/' + bid + '/pause').then(function () { loadPanel(body); }).catch(function () { loadPanel(body); }); return; }
          var br = e.target.closest && e.target.closest('.rsms-blast-resume');
          if (br) { var bid2 = br.getAttribute('data-bid'); br.disabled = true; br.textContent = '…'; api.request('POST', '/campaigns/' + bid2 + '/resume').then(function () { loadPanel(body); }).catch(function () { loadPanel(body); }); return; }
