        var bell = bar.querySelector('.icon-btn');
        if (!document.getElementById('rsms-ba-style')) { var s = document.createElement('style'); s.id = 'rsms-ba-style'; s.textContent = '.rsms-ba-on{background:#eef2ff!important}#rsms-ba-btn{position:relative}'; document.head.appendChild(s); }
        var btn = document.createElement('button');
        btn.className = bell ? bell.className : 'icon-btn'; btn.id = 'rsms-ba-btn'; btn.type = 'button';
        btn.setAttribute('aria-label', 'Bulk activity'); btn.title = 'Bulk activity';
        btn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>'
          + '<span class="rsms-ba-badge" style="display:none;position:absolute;top:0;right:0;min-width:15px;height:15px;padding:0 3px;border-radius:8px;background:#f97316;color:#fff;font-size:10px;font-weight:700;line-height:15px;text-align:center;box-sizing:border-box">0</span>';
        btn.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); openDrop(); });
        if (bell && bell.parentNode) bell.parentNode.insertBefore(btn, bell); else bar.appendChild(btn);
        refreshBadge();
